    37  #include "hb-pool.hh"
    38
    39
    40  /*
    41   * Serialize
    42   */
    43
    44  struct hb_serialize_context_t
    45  {
    46    typedef unsigned objidx_t;
    47
    48    struct range_t
    49    {
    50      char *head, *tail;
    51    };
    52
    53    struct object_t : range_t
    54    {
    55      void fini () { links.fini (); }
    56
    57      bool operator == (const object_t &o) const
    58      {
    59        return (tail - head == o.tail - o.head)
    60            && (links.length == o.links.length)
    61            && 0 == hb_memcmp (head, o.head, tail - head)
    62            && links.as_bytes () == o.links.as_bytes ();
    63      }
    64      uint32_t hash () const
    65      {
    66        return hb_bytes_t (head, tail - head).hash () ^
    67               links.as_bytes ().hash ();
    68      }
    69
    70      struct link_t
    71      {
    72        bool is_wide: 1;
    73        unsigned position : 31;
    74        unsigned bias;
    75        objidx_t objidx;
    76      };
    77
    78      hb_vector_t<link_t> links;
    79      object_t *next;
    80    };
    81
    82    range_t snapshot () { range_t s = {head, tail} ; return s; }
    83
    84
    85    hb_serialize_context_t (void *start_, unsigned int size) :
    86      start ((char *) start_),
    87      end (start + size),
    88      current (nullptr)
    89    { reset (); }
    90    ~hb_serialize_context_t () { fini (); }
    91
    92    void fini ()
    93    {
    94      ++ hb_iter (packed)
    95      | hb_apply ([] (object_t *_) { _->fini (); })
    96      ;
    97      packed.fini ();
    98      this->packed_map.fini ();
    99
   100      while (current)
   101      {
   102        auto *_ = current;
   103        current = current->next;
   104        _->fini ();
   105      }
   106      object_pool.fini ();
   107    }
   108
   109    bool in_error () const { return !this->successful; }
   110
   111    void reset ()
   112    {
   113      this->successful = true;
   114      this->ran_out_of_room = false;
   115      this->head = this->start;
   116      this->tail = this->end;
   117      this->debug_depth = 0;
   118
   119      fini ();
   120      this->packed.push (nullptr);
   121    }
   122
   123    bool check_success (bool success)
   124    { return this->successful && (success || (err_other_error (), false)); }
   125
   126    template <typename T1, typename T2>
   127    bool check_equal (T1 &&v1, T2 &&v2)
   128    { return check_success (v1 == v2); }
   129
   130    template <typename T1, typename T2>
   131    bool check_assign (T1 &v1, T2 &&v2)
   132    { return check_equal (v1 = v2, v2); }
   133
   134    template <typename T> bool propagate_error (T &&obj)
   135    { return check_success (!hb_deref (obj).in_error ()); }
   136
   137    template <typename T1, typename... Ts> bool propagate_error (T1 &&o1, Ts &&...os)
   138    { return propagate_error (hb_forward<T1> (o1)) &&
   139             propagate_error (hb_forward<Ts> (os)...); }
   140
   141    /* To be called around main operation. */
   142    template <typename Type>
   143    Type *start_serialize ()
   144    {
   145      DEBUG_MSG_LEVEL (SERIALIZE, this->start, 0, +1,
   146                       "start [%p..%p] (%lu bytes)",
   147                       this->start, this->end,
   148                       (unsigned long) (this->end - this->start));
   149
   150      assert (!current);
   151      return push<Type> ();
   152    }
   153    void end_serialize ()
   154    {
   155      DEBUG_MSG_LEVEL (SERIALIZE, this->start, 0, -1,
   156                       "end [%p..%p] serialized %u bytes; %s",
   157                       this->start, this->end,
   158                       (unsigned) (this->head - this->start),
   159                       this->successful ? "successful" : "UNSUCCESSFUL");
   160
   161      propagate_error (packed, packed_map);
   162
   163      if (unlikely (!current)) return;
   164      assert (!current->next);
   165
   166      /* Only "pack" if there exist other objects... Otherwise, don't bother.
   167       * Saves a move. */
   168      if (packed.length <= 1)
   169        return;
   170
   171      pop_pack ();
   172
   173      resolve_links ();
   174    }
   175
   176    template <typename Type = void>
   177    Type *push ()
   178    {
   179      object_t *obj = object_pool.alloc ();
   180      if (unlikely (!obj))
   181        check_success (false);
   182      else
   183      {
   184        obj->head = head;
   185        obj->tail = tail;
   186        obj->next = current;
   187        current = obj;
   188      }
   189      return start_embed<Type> ();
   190    }
   191    void pop_discard ()
   192    {
   193      object_t *obj = current;
   194      if (unlikely (!obj)) return;
   195      current = current->next;
   196      revert (*obj);
   197      object_pool.free (obj);
   198    }
   199    objidx_t pop_pack ()
   200    {
   201      object_t *obj = current;
   202      if (unlikely (!obj)) return 0;
   203      current = current->next;
   204      obj->tail = head;
   205      obj->next = nullptr;
   206      unsigned len = obj->tail - obj->head;
   207      head = obj->head; /* Rewind head. */
   208
   209      if (!len)
   210      {
   211        assert (!obj->links.length);
   212        return 0;
   213      }
   214
   215      objidx_t objidx = packed_map.get (obj);
   216      if (objidx)
   217      {
   218        obj->fini ();
   219        return objidx;
   220      }
   221
   222      tail -= len;
   223      memmove (tail, obj->head, len);
   224
   225      obj->head = tail;
   226      obj->tail = tail + len;
   227
   228      packed.push (obj);
   229
   230      if (unlikely (packed.in_error ()))
   231        return 0;
   232
   233      objidx = packed.length - 1;
   234
   235      packed_map.set (obj, objidx);
   236
   237      return objidx;
   238    }
   239
   240    void revert (range_t snap)
   241    {
   242      assert (snap.head <= head);
   243      assert (tail <= snap.tail);
   244      head = snap.head;
   245      tail = snap.tail;
   246      discard_stale_objects ();
   247    }
   248
   249    void discard_stale_objects ()
   250    {
   251      while (packed.length > 1 &&
   252             packed.tail ()->head < tail)
   253      {
   254        packed_map.del (packed.tail ());
   255        assert (!packed.tail ()->next);
   256        packed.tail ()->fini ();
   257        packed.pop ();
   258      }
   259      if (packed.length > 1)
   260        assert (packed.tail ()->head == tail);
   261    }
   262
   263    template <typename T>
   264    void add_link (T &ofs, objidx_t objidx, const void *base = nullptr)
   265    {
   266      static_assert (sizeof (T) == 2 || sizeof (T) == 4, "");
   267
   268      if (!objidx)
   269        return;
   270
   271      assert (current);
   272      assert (current->head <= (const char *) &ofs);
   273
   274      if (!base)
   275        base = current->head;
   276      else
   277        assert (current->head <= (const char *) base);
   278
   279      auto& link = *current->links.push ();
   280      link.is_wide = sizeof (T) == 4;
   281      link.position = (const char *) &ofs - current->head;
   282      link.bias = (const char *) base - current->head;
   283      link.objidx = objidx;
   284    }
   285
   286    void resolve_links ()
   287    {
   288      if (unlikely (in_error ())) return;
   289
   290      assert (!current);
   291      assert (packed.length > 1);
   292
   293      for (const object_t* parent : ++hb_iter (packed))
   294      {
   295        for (const object_t::link_t &link : parent->links)
   296        {
   297          const object_t* child = packed[link.objidx];
   298          assert (link.bias <= (size_t) (parent->tail - parent->head));
   299          unsigned offset = (child->head - parent->head) - link.bias;
   300
   301          if (link.is_wide)
   302          {
   303            auto &off = * ((BEInt<uint32_t, 4> *) (parent->head + link.position));
   304            assert (0 == off);
   305            check_assign (off, offset);
   306          }
   307          else
   308          {
   309            auto &off = * ((BEInt<uint16_t, 2> *) (parent->head + link.position));
   310            assert (0 == off);
   311            check_assign (off, offset);
   312          }
   313        }
   314      }
   315    }
   316
   317    unsigned int length () const { return this->head - current->head; }
   318
   319    void align (unsigned int alignment)
   320    {
   321      unsigned int l = length () % alignment;
   322      if (l)
   323        allocate_size<void> (alignment - l);
   324    }
   325
   326    template <typename Type>
   327    Type *start_embed (const Type *obj HB_UNUSED = nullptr) const
   328    { return reinterpret_cast<Type *> (this->head); }
   329    template <typename Type>
   330    Type *start_embed (const Type &obj) const
   331    { return start_embed (hb_addressof (obj)); }
   332
   333    /* Following two functions exist to allow setting breakpoint on. */
   334    void err_ran_out_of_room () { this->ran_out_of_room = true; }
   335    void err_other_error () { this->successful = false; }
   336
   337    template <typename Type>
   338    Type *allocate_size (unsigned int size)
   339    {
   340      if (unlikely (!this->successful)) return nullptr;
   341
   342      if (this->tail - this->head < ptrdiff_t (size))
   343      {
   344        err_ran_out_of_room ();
   345        this->successful = false;
   346        return nullptr;
   347      }
   348      memset (this->head, 0, size);
   349      char *ret = this->head;
   350      this->head += size;
   351      return reinterpret_cast<Type *> (ret);
   352    }
   353
   354    template <typename Type>
   355    Type *allocate_min ()
   356    {
   357      return this->allocate_size<Type> (Type::min_size);
   358    }
   359
   360    template <typename Type>
   361    Type *embed (const Type *obj)
   362    {
   363      unsigned int size = obj->get_size ();
   364      Type *ret = this->allocate_size<Type> (size);
   365      if (unlikely (!ret)) return nullptr;
   366      memcpy (ret, obj, size);
   367      return ret;
   368    }
   369    template <typename Type>
   370    Type *embed (const Type &obj)
   371    { return embed (hb_addressof (obj)); }
   372
   373    template <typename Type, typename ...Ts> auto
   374    _copy (const Type &src, hb_priority<1>, Ts &&...ds) HB_RETURN
   375    (Type *, src.copy (this, hb_forward<Ts> (ds)...))
   376
   377    template <typename Type> auto
   378    _copy (const Type &src, hb_priority<0>) -> decltype (&(src = src))
   379    {
   380      Type *ret = this->allocate_size<Type> (sizeof (Type));
   381      if (unlikely (!ret)) return nullptr;
   382      *ret = src;
   383      return ret;
   384    }
   385
   386    /* Like embed, but active: calls obj.operator=() or obj.copy() to transfer data
   387     * instead of memcpy(). */
   388    template <typename Type, typename ...Ts>
   389    Type *copy (const Type &src, Ts &&...ds)
   390    { return _copy (src, hb_prioritize, hb_forward<Ts> (ds)...); }
   391    template <typename Type, typename ...Ts>
   392    Type *copy (const Type *src, Ts &&...ds)
   393    { return copy (*src, hb_forward<Ts> (ds)...); }
   394
   395    template <typename Type>
   396    hb_serialize_context_t& operator << (const Type &obj) & { embed (obj); return *this; }
   397
   398    template <typename Type>
   399    Type *extend_size (Type *obj, unsigned int size)
   400    {
   401      assert (this->start <= (char *) obj);
   402      assert ((char *) obj <= this->head);
   403      assert ((char *) obj + size >= this->head);
   404      if (unlikely (!this->allocate_size<Type> (((char *) obj) + size - this->head))) return nullptr;
   405      return reinterpret_cast<Type *> (obj);
   406    }
   407    template <typename Type>
   408    Type *extend_size (Type &obj, unsigned int size)
   409    { return extend_size (hb_addressof (obj), size); }
   410
   411    template <typename Type>
   412    Type *extend_min (Type *obj) { return extend_size (obj, obj->min_size); }
   413    template <typename Type>
   414    Type *extend_min (Type &obj) { return extend_min (hb_addressof (obj)); }
   415
   416    template <typename Type, typename ...Ts>
   417    Type *extend (Type *obj, Ts &&...ds)
   418    { return extend_size (obj, obj->get_size (hb_forward<Ts> (ds)...)); }
   419    template <typename Type, typename ...Ts>
   420    Type *extend (Type &obj, Ts &&...ds)
   421    { return extend (hb_addressof (obj), hb_forward<Ts> (ds)...); }
   422
   423    /* Output routines. */
   424    hb_bytes_t copy_bytes () const
   425    {
   426      assert (this->successful);
   427      /* Copy both items from head side and tail side... */
   428      unsigned int len = (this->head - this->start)
   429                       + (this->end  - this->tail);
   430      char *p = (char *) malloc (len);
   431      if (p)
   432      {
   433        memcpy (p, this->start, this->head - this->start);
   434        memcpy (p + (this->head - this->start), this->tail, this->end - this->tail);
   435      }
   436      else
   437        return hb_bytes_t ();
   438      return hb_bytes_t (p, len);
   439    }
   440    template <typename Type>
   441    Type *copy () const
   442    { return reinterpret_cast<Type *> ((char *) copy_bytes ().arrayZ); }
   443    hb_blob_t *copy_blob () const
   444    {
   445      hb_bytes_t b = copy_bytes ();
   446      return hb_blob_create (b.arrayZ, b.length,
   447                             HB_MEMORY_MODE_WRITABLE,
   448                             (char *) b.arrayZ, free);
   449    }
   450
   451    public: /* TODO Make private. */
   452    char *start, *head, *tail, *end;
   453    unsigned int debug_depth;
   454    bool successful;
   455    bool ran_out_of_room;
   456
   457    private:
   458
   459    /* Object memory pool. */
   460    hb_pool_t<object_t> object_pool;
   461
   462    /* Stack of currently under construction objects. */
   463    object_t *current;
   464
   465    /* Stack of packed objects.  Object 0 is always nil object. */
   466    hb_vector_t<object_t *> packed;
   467
   468    /* Map view of packed objects. */
   469    hb_hashmap_t<const object_t *, objidx_t, nullptr, 0> packed_map;
   470  };
   471
   472
   473  #endif /* HB_SERIALIZE_HH */
